def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-Tat variant: donate if the recipient donated to us in the last observed interaction.
    # If no prior interaction, default to not donating.
    latest_obs = None
    for obs in observations:
        if obs['donor'] == recipient_id and obs['recipient'] == agent_id:
            if latest_obs is None or obs['round'] > latest_obs['round']:
                latest_obs = obs
    if latest_obs and latest_obs['donated']:
        return True
    return False
